BEGIN;
CREATE TABLE IF NOT EXISTS contractor_vendor_master(id uuid PRIMARY KEY,admin_tenant_id uuid NOT NULL,linked_professional_id uuid,legal_name text NOT NULL,business_name text,tax_residency text NOT NULL CHECK(tax_residency IN ('US','FOREIGN')),federal_tax_classification text NOT NULL,entity_type text NOT NULL,service_category text NOT NULL,address_line1 text,city text,state text,zip text,email text,phone text,start_date date,payment_terms text,payment_method text,w9_status text NOT NULL DEFAULT 'MISSING',foreign_tax_doc_status text NOT NULL DEFAULT 'NOT_APPLICABLE',tin_type text,tin_last4 varchar(4),tin_validation_status text NOT NULL DEFAULT 'EXTERNAL_REQUIRED',backup_withholding_status text NOT NULL DEFAULT 'REVIEW',backup_withholding_reason text,classification_status text NOT NULL DEFAULT 'PENDING_REVIEW',classification_notes text,contract_status text NOT NULL DEFAULT 'PENDING',status text NOT NULL DEFAULT 'ONBOARDING',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contractor_compensation(id uuid PRIMARY KEY,admin_tenant_id uuid NOT NULL,contractor_id uuid NOT NULL REFERENCES contractor_vendor_master(id),payment_date date NOT NULL,tax_year integer NOT NULL,gross_amount numeric(14,2) NOT NULL,reportable_amount numeric(14,2) NOT NULL,reimbursement_amount numeric(14,2) NOT NULL DEFAULT 0,payment_rail text NOT NULL,reporting_track text NOT NULL,backup_withholding_amount numeric(14,2) NOT NULL DEFAULT 0,net_amount numeric(14,2) NOT NULL,status text NOT NULL,memo text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contractor_tax_tasks(id uuid PRIMARY KEY,admin_tenant_id uuid NOT NULL,contractor_id uuid,task_key text NOT NULL,title text NOT NULL,category text NOT NULL,status text NOT NULL DEFAULT 'OPEN',priority text NOT NULL,due_date date,external_gate boolean NOT NULL DEFAULT false,reason text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE IF NOT EXISTS information_return_workfiles(id uuid PRIMARY KEY,admin_tenant_id uuid NOT NULL,contractor_id uuid REFERENCES contractor_vendor_master(id),tax_year integer NOT NULL,form_type text NOT NULL,reportable_amount numeric(14,2) NOT NULL DEFAULT 0,federal_withholding numeric(14,2) NOT NULL DEFAULT 0,preparation_status text NOT NULL DEFAULT 'DRAFT',submission_status text NOT NULL DEFAULT 'NOT_TRANSMITTED',external_submission_id text,external_ack_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_contractor_admin_status ON contractor_vendor_master(admin_tenant_id,status);
CREATE INDEX IF NOT EXISTS idx_compensation_admin_year ON contractor_compensation(admin_tenant_id,tax_year,payment_date);
CREATE INDEX IF NOT EXISTS idx_tax_tasks_admin_status ON contractor_tax_tasks(admin_tenant_id,status,due_date);
CREATE INDEX IF NOT EXISTS idx_info_return_admin_year ON information_return_workfiles(admin_tenant_id,tax_year,form_type);
COMMIT;